const int panjangPerBaris = 260; 

void tampilkanHitOrMiss(Player playerAsal, Player playerTujuan){
    std::this_thread::sleep_for(std::chrono::microseconds(100));
    if(playerAsal.apakahAdaYangKena(playerTujuan) && playerAsal.apakahAdaYangKenaKapal(playerTujuan)){
        tampilkanTanpaErase(hit);
        const int banyaknya_frame = 8;
        for(int i = 0; i < banyaknya_frame; i++){
            tampilkanCepat(kapalHancur[i]);
            std::this_thread::sleep_for(std::chrono::milliseconds(200));
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
        Erase_Screen();
    }
    else if(playerAsal.apakahAdaYangKena(playerTujuan)){
        tampilkan(hit);
    }
    else tampilkan(miss);
}

